import six
from .exceptions import NoSuchId, MissingId
from .notifying_creator import NotifyingCreator
from .singleton import ThreadSafeSingleton


@six.add_metaclass(NotifyingCreator)
class NetworkElementIdentification(dict):
    """Identify same network element via different identifiers - helps in finding that we talk to same NE"""
    def __init__(self, identifiers, network_elem_type, specific_for_tool=None):  # pylint: disable=super-init-not-called
        """
        Create NE identification based on multiple identifiers referring same NE
        :param identifiers: iterable of pairs (id_type, identifier)
        :param network_elem_type: type of NE pointed by this identification
        :param specific_for_tool: (if given) name of tool that is using this id_type to identify NE
        :raises: :py:class:`ute_common_abstract_core.exceptions.MissingId`: if tool-specific-id not inside identifiers when specific_for_tool is given
        """
        assert identifiers
        assert len(identifiers[0]) == 2

        self.network_elem_type = network_elem_type
        self.specific_for_tool = None

        for (id_type, identifier) in identifiers:
            self[id_type] = identifier
            if specific_for_tool and (id_type == specific_for_tool):
                self.specific_for_tool = specific_for_tool

        if specific_for_tool and (specific_for_tool not in self):
            msg = f"Identification is {specific_for_tool}-specific but '{specific_for_tool}' id is missing; known ids: {self.__known_ids()}"
            raise MissingId(msg)

    @classmethod
    def from_type_id_pairs(cls, identifiers, network_elem_type, specific_for_tool=None):
        """
        Alternate construction based on multiple identifiers referring same NE.

        :param identifiers: iterable of pairs (id_type, identifier)
        :param specific_for_tool:
        :param network_elem_type:
        :return: new NetworkElementIdentification
        :raises: :py:class:`ute_common_abstract_core.exceptions.MissingId`: if tool-specific-id not inside identifiers when specific_for_tool is given
        """
        self = cls(identifiers, network_elem_type, specific_for_tool)
        return self

    def __eq__(self, other):
        NetworkElementIdentification._assert_comparing_same_types(other)
        if self.network_elem_type != other.network_elem_type:
            return False
        smaller, bigger = self.__sort_by_number_of_identifiers(other)
        for id_type, _ in smaller.items():
            if id_type not in bigger:
                return False
            if bigger[id_type] != smaller[id_type]:
                return False
        return True

    def __ne__(self, other):
        return not self.__eq__(other)

    def __repr__(self):
        ids_str = self.__known_ids()
        ne_type = self.network_elem_type
        if self.specific_for_tool:
            ne_type = f"{self.specific_for_tool}-{self.network_elem_type}"
        return f"{ne_type}({ids_str})"

    def __missing__(self, key):
        """
        Accessing nonexisting id_type via xxx[id_type] raises NoSuchId

        :param key: id_type
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.NoSuchId`: if no such id_type inside known identifications
        """
        raise NoSuchId("No id for type '%s', known ids by types: %s" % (key, self.__known_ids()))

    @property
    def alias(self):
        """Return value of 'alias' identifier"""
        return self['alias']

    @property
    def tool_specific_id(self):
        """
        Return value of tool specific identifier of NE
        :raises: :py:class:`ute_common_abstract_core.exceptions.MissingId`: if NE Identification was created as not-tool-specific
        """
        if self.specific_for_tool:
            return self[self.specific_for_tool]
        raise MissingId(f"Identification is not tool-specific - don't know which id to return; known ids: {self.__known_ids()}")

    def __known_ids(self):
        ids_str = super(NetworkElementIdentification, self).__repr__()
        return ids_str

    def __sort_by_number_of_identifiers(self, other):
        if len(other) < len(self):
            smaller = other
            bigger = self
        else:
            smaller = self
            bigger = other
        return smaller, bigger

    @staticmethod
    def _assert_comparing_same_types(other):
        if not isinstance(other, NetworkElementIdentification):
            raise TypeError(f"object to compare must be NetworkElementIdentification and not {type(other)}")


class EndpointsIp(set):
    def __eq__(self, other):
        if isinstance(other, EndpointsIp) is False:
            return False
        smaller, bigger = self.__sort_by_number_of_identifiers(other)
        return True if smaller.issubset(bigger) else False

    def __sort_by_number_of_identifiers(self, other):
        if len(other) < len(self):
            smaller = other
            bigger = self
        else:
            smaller = self
            bigger = other
        return smaller, bigger

    def __ne__(self, other):
        return not self.__eq__(other)


@six.add_metaclass(ThreadSafeSingleton)
class MsgSourceIdentificationFactory:
    """Factory of MsgSourceIdentification"""
    def __init__(self):
        """Basic initialization."""
        self._elems_registry = {}

    def register_construction(self, network_elem_type, variant, msg_src_id_constructor):
        """
        Register function that will return MsgSourceIdentification
        :param network_elem_type: 'UE', 'MME', 'ENB', ...
        :param variant: implementation variant, ex. for 'UE' it might be 'wts', 'qualcomm', 'android', ...
        :param msg_src_id_constructor: function
        :return: None
        """
        self._elems_registry[(network_elem_type, variant)] = msg_src_id_constructor

    def create_msg_src_id(self, identifiers, network_elem_type, variant, specific_for_tool=None):
        """
        Return MsgSourceIdentification instance
        :param identifiers: iterable of pairs (id_type, identifier)
        :param network_elem_type: which type we want (UE/MME/ENB...)
        :param variant: which variant of that type we want
        :param specific_for_tool: name of tool that is using this id_type to identify NE
        :return: MsgSourceIdentification instance
        """
        requested_element_key = (network_elem_type, variant)
        if requested_element_key in self._elems_registry:
            return self._elems_registry[requested_element_key](identifiers, network_elem_type, specific_for_tool)
        else:
            return MsgSourceIdentification(identifiers, network_elem_type, specific_for_tool)


class MsgSourceIdentification(NetworkElementIdentification):
    """Identify Message Source(s) of given NetworkElementIdentification"""
    pass  # pylint: disable=unnecessary-pass


